        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "value": 0
          },
          "width": {
            "signal": "width"
          },
          "height": {
            "value": 32
          },
          "fill": {
            "value": "#172438"
          }
        }
      }
    },
    {
